with unpacked as (select id, status_code, payload_json, size(context) as num_context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, coalesce(context['version'], 'none') as version_or_default, shiftright(status_code, 2) as status_code_high from app_logs) select case when status_code >= 460 then 'LARGE' else 'SMALL' end as status_code_tier, case when status_code_high >= 2 then 'PREMIUM' else 'STANDARD' end as status_code_high_tier, percentile_approx(duration_sec, array(0.25, 0.5, 0.75)) as duration_sec_quartiles, round(avg(num_context), 2) as avg_num_context from unpacked group by 1, 2 having avg_num_context >= 0 order by status_code_tier
